  flex: 1;
  width: 100%;
  height: 100%; /* 确保高度填满父容器 */
  padding-bottom: 20px;
  box-sizing: border-box;
  scrollbar-width: none;
  position: relative;
  overflow-y: auto; /* 改为auto，在需要时显示滚动条 */
  -webkit-overflow-scrolling: touch; /* iOS平滑滚动 */
}

/* 隐藏滚动条 */
.shared-msg-list::-webkit-scrollbar {
  display: none;
}

.loading-more {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px 0;
  color: var(--text-description);
  font-size: 14px;
}

.no-more-data {
  display: flex;
